protected void performExplicitRegistration(final OidcConfiguration configuration,
                                               final OIDCProviderMetadata metadata,
                                               final String entityId,
                                               final JWKSet federationJWKS) {
        val registrationEndpoint = metadata.getFederationRegistrationEndpointURI();
        if (registrationEndpoint == null) {
            throw new OidcException("Client registration endpoint is not defined and only explicit registration is accepted by the OP");
        }
        LOGGER.debug("Registration endpoint exists and only explicit registration by OP (and RP) -> performing explicit registration");

        val generator = configuration.getFederation().getEntityConfigurationGenerator();
        val entityConfig = generator.generateEntityStatement();

        String clientId = null;
        try {
            val request = new HTTPRequest(HTTPRequest.Method.POST, registrationEndpoint);
            request.setContentType(EntityStatement.CONTENT_TYPE.toString());
            request.setBody(entityConfig);
            configuration.configureHttpRequest(request);
            val response = request.send();
            val code = response.getStatusCode();
            val error = response.getStatusMessage();
            val content = response.getContent();
            if (code == 200 || code == 201) {
                LOGGER.debug("Received response registration: {}", content);
                val statement = ExplicitRegistrationResponse.parse(content);
                val type = statement.getSignedStatement().getHeader().getType();
                if (type != null && !JOSEObjectType.JWT.equals(type) &&
                    !ExplicitRegistrationResponse.EXPLICIT_RESPONSE_JOSE_OBJECT_TYPE.equals(type)) {
                    throw new OidcException("Unexpected explicit registration response typ: " + type);
                }
                statement.verifySignature(federationJWKS);
                // jwks property is optional in the registration response
                val claimsVerifier = new EntityStatementClaimsVerifier(new Audience(entityId));
                claimsVerifier.verify(statement.getSignedStatement().getJWTClaimsSet(), null);
                val expectedIssuer = metadata.getIssuer().getValue();
                val issuer = statement.getClaimsSet().getIssuerEntityID();
                if (issuer == null || !expectedIssuer.equals(issuer.getValue())) {
                    throw new OidcException("Unexpected explicit registration response issuer: " + issuer);
                }
                val payload = statement.getSignedStatement().getPayload().toString();
                val data = OBJECT_MAPPER.readTree(payload);
                val orp = data.path("metadata").path("openid_relying_party");
                clientId = orp.path("client_id").asText();
                if (StringUtils.isNotBlank(clientId)) {
                    configuration.setClientId(clientId);
                    logSeparator();
                    LOGGER.warn("/!\\ Explicit registration of the client '{}' returns id: [{}]. This information won't be repeated. "
                        + "You MUST add this value to your configuration before the next application startup!", entityId, clientId);
                    val clientSecret = orp.path("client_secret").asText();
                    if (StringUtils.isNotBlank(clientSecret)) {
                        val secretExportFile = configuration.getFederation().getSecretExportFile();
                        if (isBlank(secretExportFile)) {
                            throw new OidcException("Client secret export file is required");
                        }
                        configuration.setSecret(clientSecret);
                        LOGGER.warn("/!\\ The received secret has been saved into the file: {}", secretExportFile);
                        val path = Path.of(secretExportFile);
                        FileHelper.savePrivateFile(path, clientSecret);
                    }
                    logSeparator();
                    val scope = orp.path("scope").asText();
                    if (StringUtils.isNotBlank(scope)) {
                        configuration.setScope(scope);
                    }
                    val tokenEndpointAuthMethod = orp.path("token_endpoint_auth_method").asText();
                    if (StringUtils.isNotBlank(tokenEndpointAuthMethod)) {
                        val clientAuthenticationMethod = ClientAuthenticationMethod.parse(tokenEndpointAuthMethod);
                        if (!DefaultClientAuthenticationBuilder.SUPPORTED_METHODS.contains(clientAuthenticationMethod)) {
                            throw new OidcException(
                                "Unsupported token_endpoint_auth_method returned by explicit registration: " + tokenEndpointAuthMethod);
                        }
                        configuration.setClientAuthenticationMethod(clientAuthenticationMethod);
                    }
                    val requestObjectSigningAlg = orp.path("request_object_signing_alg").asText();
                    if (StringUtils.isNotBlank(requestObjectSigningAlg)) {
                        configuration.setRequestObjectSigningAlgorithm(JWSAlgorithm.parse(requestObjectSigningAlg));
                    }
                    val idTokenSigningAlg = orp.path("id_token_signed_response_alg").asText();
                    if (StringUtils.isNotBlank(idTokenSigningAlg)) {
                        configuration.setIdTokenSigningAlgorithmAsString(idTokenSigningAlg);
                    }
                    val responseTypes = getStringList(orp.path("response_types"));
                    if (!responseTypes.isEmpty()) {
                        val selectedResponseType = PREFERRED_RESPONSE_TYPES.stream()
                            .flatMap(Collection::stream)
                            .filter(preferredResponseType -> responseTypes.contains(preferredResponseType.toString()))
                            .findFirst()
                            .orElseThrow(() -> new OidcException(
                                "No supported response_type returned by explicit registration: " + responseTypes));
                        configuration.setResponseType(selectedResponseType.toString());
                    }
                }
            }
            if (isBlank(clientId)) {
                throw new OidcException("Cannot explicitely register the client " + entityId
                    + "(code=" + code + ",error=" + error + ",content=" + content + ")");
            }
        } catch (final IOException | JOSEException | BadJOSEException | ParseException
                       | com.nimbusds.oauth2.sdk.ParseException e) {
            LOGGER.error("Explicit registration fails, no automatic option -> failing definitely");
            throw new TechnicalException(e);
        }
    }

public static JWSAlgorithm determineAlgorithm(final JWK key, final boolean allowSymmetricSigning) {
        if (key.getAlgorithm() != null) {
            return JWSAlgorithm.parse(key.getAlgorithm().getName());
        }

        if (key instanceof OctetKeyPair) {
            return JWSAlgorithm.EdDSA;
        } else if (key instanceof ECKey ecKey) {
            val curve = ecKey.getCurve();
            if (curve == null) {
                throw new TechnicalException("ECKey without curve");
            }

            if (Curve.P_256.equals(curve) || Curve.SECP256K1.equals(curve)) {
                return JWSAlgorithm.ES256;
            } else if (Curve.P_384.equals(curve)) {
                return JWSAlgorithm.ES384;
            } else if (Curve.P_521.equals(curve)) {
                return JWSAlgorithm.ES512;
            } else {
                throw new TechnicalException("Unsupported EC curve: " + curve.getName());
            }
        } else if (key instanceof RSAKey rsaKey) {
            val bitLength = rsaKey.getModulus().decodeToBigInteger().bitLength();
            if (bitLength >= 4096) {
                return JWSAlgorithm.RS512;
            } else if (bitLength >= 3072) {
                return JWSAlgorithm.RS384;
            } else {
                return JWSAlgorithm.RS256;
            }
        } else if (key instanceof OctetSequenceKey || key instanceof SecretKey) {
            if (!allowSymmetricSigning) {
                throw new TechnicalException("Symmetric keys (OctetSequenceKey / SecretKey) are not allowed");
            }

            byte[] keyBytes;
            if (key instanceof OctetSequenceKey osk) {
                keyBytes = osk.toByteArray();
            } else {
                keyBytes = ((SecretKey) key).getEncoded();
                if (keyBytes == null) {
                    throw new TechnicalException("Cannot get encoded bytes from SecretKey");
                }
            }

            val keyLengthBits = keyBytes.length * 8;
            if (keyLengthBits >= 512) {
                return JWSAlgorithm.HS512;
            }
            if (keyLengthBits >= 384) {
                return JWSAlgorithm.HS384;
            }
            if (keyLengthBits >= 256) {
                return JWSAlgorithm.HS256;
            }

            throw new TechnicalException("Symmetric key too short for secure HMAC: " + keyLengthBits + " bits ");
        }

        throw new TechnicalException("Unsupported key type: " + key.getClass().getSimpleName());
    }
